PRAGMA foreign_keys = off;
CREATE TABLE `journal_entries` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `created_at` datetime NOT NULL, `updated_at` datetime NOT NULL, `job_id` text NOT NULL, `device_id` text NULL, `attempt` integer NOT NULL, `node_id` text NOT NULL, `run_id` text NOT NULL, `sequence` integer NOT NULL, `dag_id` text NULL, `dag_version` text NULL, `fqcn` text NULL, `fqcn_unresolved` bool NOT NULL DEFAULT (false), `task_name` text NULL, `register` text NULL, `started_at` datetime NULL, `finished_at` datetime NULL, `outcome` text NOT NULL, `failure_stage` text NULL, `skip_kind` text NULL, `skip_ordinal` integer NOT NULL DEFAULT (0), `skip_total` integer NOT NULL DEFAULT (0), `stat_keys` json NULL, `undeclared_stat_count` integer NOT NULL DEFAULT (0), `param_keys` json NULL, `undeclared_param_count` integer NOT NULL DEFAULT (0), `inverse_fqcn` text NULL, `inverse_fqcn_unresolved` bool NOT NULL DEFAULT (false), `inverse_param_keys` json NULL, `undeclared_inverse_param_count` integer NOT NULL DEFAULT (0), `diff_recorded` bool NOT NULL DEFAULT (false));
CREATE UNIQUE INDEX `journalentry_job_id_device_id_attempt_node_id` ON `journal_entries` (`job_id`, `device_id`, `attempt`, `node_id`);
CREATE INDEX `journalentry_job_id_device_id_attempt_sequence` ON `journal_entries` (`job_id`, `device_id`, `attempt`, `sequence`);
PRAGMA foreign_keys = on;
